    def clamp_step(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    def dist1(p, q):
        return abs(p[0] - q[0]) + abs(p[1] - q[1])

    def best_by(items, key):
        best_item = None
        best_score = None
        for item in items:
            try:
                score = key(item)
